<?php session_start(); require 'conectare.php'; $q=trim($_GET['cuvant']??''); $like='%'.$q.'%'; $sa=$pdo->prepare('SELECT id_autor,nume_autor FROM autori WHERE nume_autor LIKE ? ORDER BY nume_autor');$sa->execute([$like]);$authors=$sa->fetchAll();$st=$pdo->prepare('SELECT id_carte,titlu FROM carti WHERE titlu LIKE ? ORDER BY titlu');$st->execute([$like]);$titles=$st->fetchAll();$sd=$pdo->prepare('SELECT id_carte,titlu,descriere FROM carti WHERE descriere LIKE ? ORDER BY titlu');$sd->execute([$like]);$descs=$sd->fetchAll();include 'page_top.php';include 'meniu.php';?>
<td valign="top"><h1>Rezultatele cautarii</h1><p>Textul cautat: <b><?=h($q)?></b></p><b>Autori</b><blockquote><?php if(!$authors) echo '<i>Nici un rezultat!</i>'; foreach($authors as $a):?><a href="autor.php?id_autor=<?=(int)$a['id_autor']?>"><?=h($a['nume_autor'])?></a><br><?php endforeach;?></blockquote><b>Titluri</b><blockquote><?php if(!$titles) echo '<i>Nici un rezultat!</i>'; foreach($titles as $b):?><a href="carte.php?id_carte=<?=(int)$b['id_carte']?>"><?=h($b['titlu'])?></a><br><?php endforeach;?></blockquote><b>Descrieri</b><blockquote><?php if(!$descs) echo '<i>Nici un rezultat!</i>'; foreach($descs as $b):?><a href="carte.php?id_carte=<?=(int)$b['id_carte']?>"><?=h($b['titlu'])?></a><br><?=h($b['descriere'])?><br><br><?php endforeach;?></blockquote></td><?php include 'page_bottom.php';?>
